pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testRegression_property() public {
        c.Initialized();
        bool ok;
        try c.SetMinSum(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
